import{_ as i,o as e,c as l,aw as t}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react-hooks/main/info.md","filePath":"wiki/dev-commit/framework-react/react-hooks/main/info.md"}'),o={name:"wiki/dev-commit/framework-react/react-hooks/main/info.md"};function r(c,a,n,s,m,d){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><h2 id="информация-1" tabindex="-1">Информация <a class="header-anchor" href="#информация-1" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Хуки</p><ul><li><strong>Хуки (React 16.8)</strong> - функции JavaScript, которые позволяют использовать состояние, методы жизненного цикла и другие возможности React из функциональных компонентов</li></ul></div><ul><li>Хуки позволяют вам повторно использовать логику состояния, не затрагивая дерево компонентов. Благодаря этому, хуки легко использовать в разных компонентах и делиться ими с сообществом</li><li>Хуки работают рядом с существующим кодом, поэтому вы можете внедрять их постепенно</li></ul><h2 id="правила-хуков" tabindex="-1">Правила хуков <a class="header-anchor" href="#правила-хуков" aria-label="Permalink to &quot;Правила хуков&quot;">​</a></h2><p><strong>Можно использовать внутри:</strong></p><ul><li>Функциональные компоненты</li><li>Пользовательские хуки</li></ul><p><strong>Нельзя использовать внутри:</strong></p><ul><li>Классы</li><li>Обычные JavaScript-функции</li><li>Циклы</li><li>Условия</li><li>Вложенные функции</li></ul><h2 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h2><ul><li>Делают переиспользование удобнее</li><li>Позволяют писать более интуитивно-понятный код</li><li>Избавляют от жизненного цикла</li></ul><h2 id="решаемые-проблемы" tabindex="-1">Решаемые проблемы <a class="header-anchor" href="#решаемые-проблемы" aria-label="Permalink to &quot;Решаемые проблемы&quot;">​</a></h2><ul><li><em>Трудно повторно использовать логику состояний между компонентами</em>. В React нет способа «присоединить» повторно используемое поведение к компоненту (например, подключение к хранилищу)</li><li><em>Сложные компоненты становятся трудными для понимания</em>. Каждый метод жизненного цикла часто содержит смесь несвязанной логики. Хуки позволяют разбить один компонент на маленькие функции по их назначению (например, подписке или загрузке данных), а не на основе методов жизненного цикла. Вы также можете контролировать внутреннее состояние с помощью редюсера, чтобы поведение было более предсказуемым</li><li><em>Классы создают существенный барьер в изучении React</em>. Хуки позволяют использовать больше возможностей React без написания классов. Концептуально, React-компоненты всегда были ближе к функциям</li></ul>',13)])])}const _=i(o,[["render",r]]);export{u as __pageData,_ as default};
